src='''def transform(grid):
    h, w = len(grid), len(grid[0])
    base = grid[0][0]
    left_w = next((c for c, v in enumerate(grid[0]) if v == 0), w)
    separators = [r for r in range(h) if all(grid[r][c] == base for c in range(left_w))]
    colors = sorted({v for row in grid for v in row if v not in (0, base)})
    objects = {}
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(left_w, w) if grid[r][c] == color]
        if pts:
            r0, c0 = min(r for r, c in pts), min(c for r, c in pts)
            objects[color] = {(r-r0, c-c0) for r, c in pts}
    out = [row[:left_w] for row in grid]
    for top, bottom in zip(separators, separators[1:]):
        if bottom <= top + 1:
            continue
        holes = {(r-top-1, c-1) for r in range(top+1, bottom) for c in range(1, left_w-1) if grid[r][c] == 0}
        ph, pw = bottom-top-1, left_w-2
        for color, shape in objects.items():
            for dy in range(ph):
                for dx in range(pw):
                    if {(r+dy,c+dx) for r,c in shape} == holes:
                        for r,c in holes:
                            out[top+1+r][1+c] = color
                        break
                else:
                    continue
                break
    return out
'''
